@sig trait DemandQualification_Api {
  def id: Art.BridgeId
  def demand_boundary_facts_Id : Art.PortId
  def demand_facts_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var demand_facts: Factory_Material_Continuity_Coordinator.DemandFacts = $

  def put_demand_facts(value : Factory_Material_Continuity_Coordinator.DemandFacts) : Unit = {
    Contract(
      Modifies(demand_facts),
      Ensures(
        demand_facts == value
      )
    )
    Spec {
      demand_facts = value
    }

    Art.putValue(demand_facts_Id, Factory_Material_Continuity_Coordinator.DemandFacts_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class DemandQualification_Initialization_Api (
  val id: Art.BridgeId,
  val demand_boundary_facts_Id : Art.PortId,
  val demand_facts_Id : Art.PortId) extends DemandQualification_Api

@datatype class DemandQualification_Operational_Api (
  val id: Art.BridgeId,
  val demand_boundary_facts_Id : Art.PortId,
  val demand_facts_Id : Art.PortId) extends DemandQualification_Api {

  // Logika spec var representing port state for incoming data port
  @spec var demand_boundary_facts: Factory_Material_Continuity_Coordinator.DemandBoundaryFacts = $

  def get_demand_boundary_facts() : Option[Factory_Material_Continuity_Coordinator.DemandBoundaryFacts] = {
    Contract(
      Ensures(
        Res == Some(demand_boundary_facts)
      )
    )
    val value : Option[Factory_Material_Continuity_Coordinator.DemandBoundaryFacts] = Art.getValue(demand_boundary_facts_Id) match {
      case Some(Factory_Material_Continuity_Coordinator.DemandBoundaryFacts_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port demand_boundary_facts.  Expecting 'Factory_Material_Continuity_Coordinator.DemandBoundaryFacts_Payload' but received ${v}")
        None[Factory_Material_Continuity_Coordinator.DemandBoundaryFacts]()
      case _ => None[Factory_Material_Continuity_Coordinator.DemandBoundaryFacts]()
    }
    return value
  }
}
